// ===== GOALS SYNC CONFIG =====
const SPREADSHEET_ID = '1L4jaTxPdlKMvzFme73McVRqzRJqLrJvaJ0Xxdgy-E0c';
return [{ json: { SPREADSHEET_ID } }];

const esc = v => v === null || v === undefined || v === '' ? 'NULL' : "'" + String(v).replace(/'/g, "''") + "'";
const num = v => v === null || v === undefined || v === '' || isNaN(Number(v)) ? 'NULL' : String(Number(v));
const bool = v => v ? 'true' : 'false';

const VALID = ['responded','discovery','qualified','opportunity','customer','calls','won_value'];
const rows = $input.all().map(i => i.json).filter(r => r && r.metric && r.period && r.target !== undefined && r.target !== '');
const good = rows.filter(r => VALID.includes(String(r.metric).trim().toLowerCase()) && !isNaN(Number(r.target)));
const stmts = ['BEGIN;'];
if (good.length) {
  stmts.push('INSERT INTO goals (metric,period,target,label,updated_at) VALUES\n' +
    good.map(r => '(' + [esc(String(r.metric).trim().toLowerCase()), esc(String(r.period).trim()),
      num(r.target), esc(r.label || ''), esc(new Date().toISOString())].join(',') + ')').join(',\n') +
    '\nON CONFLICT (metric,period) DO UPDATE SET target=EXCLUDED.target, label=EXCLUDED.label, updated_at=EXCLUDED.updated_at;');
  stmts.push('DELETE FROM goals WHERE (metric,period) NOT IN (' +
    good.map(r => '(' + esc(String(r.metric).trim().toLowerCase()) + ',' + esc(String(r.period).trim()) + ')').join(',') + ');');
} else { stmts.push('DELETE FROM goals;'); }
stmts.push('COMMIT;');
return [{ json: { sql: stmts.join('\n') } }];
